const items = $input.all();
const now = Date.now();

if (items.length === 0) return [];

return items.map(item => {
  const ts = item.json['timestamp'];
  let weekNum = 1;
  if (ts) {
    const daysSince = Math.floor((now - new Date(ts).getTime()) / (24 * 60 * 60 * 1000));
    weekNum = Math.max(1, Math.ceil(daysSince / 7));
  }
  return { json: { ...item.json, weekNumber: weekNum } };
});

const aiResps = $input.all();
const clients = $('🔢 Calculate Week Number').all();

return aiResps.map((aiResp, i) => {
  const client = clients[i]?.json || {};
  let email = {};
  try {
    const raw = aiResp.json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    email = JSON.parse(raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
  } catch (e) {
    email = {
      subject: `Week ${client.weekNumber} Check-In \u2014 ${client.serviceRequired} for ${client.clientCompany}`,
      body: `Hi ${client.clientName},\n\nHappy Monday! We are now in Week ${client.weekNumber} of the ${client.serviceRequired} project. Everything is moving along smoothly and we are on track with our milestones.\n\nDo you have any questions or feedback for us this week?\n\nBest regards,\n${client.yourName}`
    };
  }

  const htmlBody = `<!DOCTYPE html><html><head><style>body{font-family:'Segoe UI',Tahoma,Geneva,Verdana,sans-serif;line-height:1.6;color:#1a202c;margin:0;padding:0;background-color:#f7fafc}.container{max-width:600px;margin:20px auto;border-radius:16px;overflow:hidden;background-color:#fff;box-shadow:0 10px 25px rgba(0,0,0,.1)}.header{background:linear-gradient(135deg,#10b981,#3b82f6);color:#fff;padding:40px 20px;text-align:center}.content{padding:40px}.footer{background-color:#f8fafc;padding:20px;text-align:center;font-size:13px;color:#718096;border-top:1px solid #edf2f7}.badge{display:inline-block;padding:4px 12px;background:#e0f2fe;color:#0369a1;border-radius:9999px;font-size:12px;font-weight:700;text-transform:uppercase;margin-bottom:15px}.button{display:inline-block;padding:14px 30px;background:linear-gradient(135deg,#10b981,#3b82f6);color:#fff!important;text-decoration:none;border-radius:12px;font-weight:700;margin-top:25px}.highlight{color:#2563eb;font-weight:700}</style></head><body><div class="container"><div class="header"><h1 style="margin:0;font-size:28px">Weekly Project Check-In</h1><p style="margin:8px 0 0;font-size:16px;opacity:.9">Week ${client.weekNumber} Status Update</p></div><div class="content"><div class="badge">On Track</div><p style="font-size:18px">Hi <span class="highlight">${client.clientName}</span>,</p><p style="font-size:16px;color:#4a5568">${(email.body || '').replace(/\n/g, '<br>')}</p><div style="text-align:center;margin-top:30px"><a href="mailto:${client.clientEmail}" class="button">Reply with Feedback</a></div></div><div class="footer"><p>Sent by <strong>${client.agencyName}</strong></p><p style="margin-top:0">Dedicated to ${client.clientCompany}'s success</p></div></div></body></html>`;

  return { json: { ...client, checkInSubject: email.subject, checkInBody: htmlBody } };
});

// Global Config (cogdef) - Pulling from Environment Variables
const config = {
  safeMode: $env.SAFE_MODE === 'true',
  logDrainId: $env.LOG_DRAIN_ID || "FEK7PNwR6I3XZygD",
  spreadsheetId: $env.SPREADSHEET_ID || "16dAe64XCQ_iecfAlrrdG5n6TtJyr2cDrMmIN4Uv9xBU",
  env: $env.NODE_ENV || "production",
  roiMins: 45
};

return $input.all().map(item => ({
  json: { 
    ...item.json,
    ...config,
    cogdef: config 
  }
}));
